/* Reads the CSV database at build time (and on every request in `pnpm dev`), checks it, and returns typed data.
 * Any problem stops the build with a list of what to fix.
 *
 * Two places are read and merged:
 *   data/      hand-curated: categories, muscle groups, muscles, and the first exercises (with ratings)
 *   data/ms/   imported (generated by `pnpm ms:build`): more exercises, their ratings, joint scores, EMG sources
 * Muscles, groups and categories only come from data/. */
import fs from "node:fs";
import path from "node:path";
import { DEMOS } from "@/data/demos";
import { JOINTS, SHAPE_IDS } from "./anatomy";
import { readCsvTable, splitList, type CsvRow } from "./csv";
import { DRILL_KINDS, REGIONS, type Basis, type Category, type DrillKind, type EvidenceSource, type Exercise, type FullData, type Muscle, type MuscleGroup, type Region } from "./types";

export const DATA_DIR = path.join(process.cwd(), "data");
export const IMPORT_DIR = path.join(DATA_DIR, "ms");
/** [directory, file] pairs; the loader's cache is keyed on their modification times */
const FILES = {
  categories: [DATA_DIR, "categories.csv"],
  groups: [DATA_DIR, "muscle_groups.csv"],
  muscles: [DATA_DIR, "muscles.csv"],
  exercises: [DATA_DIR, "exercises.csv"],
  scores: [DATA_DIR, "exercise_muscles.csv"],
  importedExercises: [IMPORT_DIR, "exercises.csv"],
  importedScores: [IMPORT_DIR, "exercise_muscles.csv"],
  joints: [IMPORT_DIR, "exercise_joints.csv"],
  sources: [path.join(IMPORT_DIR, "evidence"), "sources.csv"],
} as const;

const SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

export class DataError extends Error {
  constructor(public problems: string[]) {
    super(
      `The CSV data has ${problems.length} problem${problems.length === 1 ? "" : "s"}:\n` +
        problems.map((p) => "  • " + p).join("\n"),
    );
    this.name = "DataError";
  }
}

export interface LoadResult { data: FullData; warnings: string[] }

let cache: { key: string; result: LoadResult } | null = null;

/** Loads and validates the CSV database. Cached until one of the files changes. */
export function loadMuscleGraphData(): LoadResult {
  const key = Object.values(FILES).map(([d, f]) => { try { return fs.statSync(path.join(d, f)).mtimeMs; } catch { return 0; } }).join("|");
  if (cache && cache.key === key) return cache.result;
  const result = parseAll();
  cache = { key, result };
  if (result.warnings.length) {
    const shown = result.warnings.slice(0, 8);
    console.warn(`[muscle-graph] ${result.warnings.length} data warnings:\n` + shown.map((w) => "  • " + w).join("\n") +
      (result.warnings.length > shown.length ? `\n  … and ${result.warnings.length - shown.length} more (run \`pnpm check-data\` for the list)` : ""));
  }
  return result;
}

const rel = (dir: string, file: string) => path.relative(process.cwd(), path.join(dir, file));

function read([dir, file]: readonly [string, string], required: string[], problems: string[], optional = false): CsvRow[] {
  const full = path.join(dir, file), name = rel(dir, file);
  if (!fs.existsSync(full)) { if (!optional) problems.push(`${name}: file not found`); return []; }
  try {
    return readCsvTable(fs.readFileSync(full, "utf8"), name, required);
  } catch (e) {
    problems.push((e as Error).message.startsWith(name) ? (e as Error).message : `${name}: ${(e as Error).message}`);
    return [];
  }
}

function parseAll(): LoadResult {
  const problems: string[] = [], warnings: string[] = [];
  const at = (f: readonly [string, string], r: CsvRow) => `${rel(...f)} line ${r.__line}`;
  const isRegion = (v: string): v is Region => (REGIONS as string[]).indexOf(v) >= 0;

  /* categories */
  const categories: Category[] = [];
  read(FILES.categories, ["id", "name"], problems).forEach((r) => {
    const where = at(FILES.categories, r);
    if (!SLUG.test(r.id)) return problems.push(`${where}: id "${r.id}" must be lowercase words joined by hyphens, e.g. "glutes-hamstrings"`);
    if (categories.some((c) => c.id === r.id)) return problems.push(`${where}: duplicate category id "${r.id}"`);
    if (!r.name) return problems.push(`${where}: name is empty`);
    categories.push({ id: r.id, name: r.name });
  });

  /* muscle groups (Basic view) */
  const groups: MuscleGroup[] = [];
  read(FILES.groups, ["id", "name", "region"], problems).forEach((r) => {
    const where = at(FILES.groups, r);
    if (!SLUG.test(r.id)) return problems.push(`${where}: id "${r.id}" must be lowercase words joined by hyphens`);
    if (groups.some((g) => g.id === r.id)) return problems.push(`${where}: duplicate group id "${r.id}"`);
    if (!r.name) return problems.push(`${where}: name is empty`);
    if (!isRegion(r.region)) return problems.push(`${where}: region "${r.region}" must be one of ${REGIONS.join(", ")}`);
    groups.push({ id: r.id, name: r.name, region: r.region });
  });
  const groupIds = new Set(groups.map((g) => g.id));

  /* muscles (Advanced view) */
  const muscles: Muscle[] = [];
  read(FILES.muscles, ["id", "name", "short_name", "region", "group"], problems).forEach((r) => {
    const where = at(FILES.muscles, r);
    if (!SLUG.test(r.id)) return problems.push(`${where}: id "${r.id}" must be lowercase words joined by hyphens`);
    if (muscles.some((m) => m.id === r.id)) return problems.push(`${where}: duplicate muscle id "${r.id}"`);
    if (!r.name) return problems.push(`${where}: name is empty`);
    if (!isRegion(r.region)) return problems.push(`${where}: region "${r.region}" must be one of ${REGIONS.join(", ")}`);
    if (r.group && !groupIds.has(r.group)) return problems.push(`${where}: group "${r.group}" is not an id in ${FILES.groups[1]}`);
    if (!SHAPE_IDS.has(r.id)) warnings.push(`${where}: muscle "${r.id}" has no shape on the body map (src/lib/anatomy-data.ts), so it won't be drawn`);
    muscles.push({ id: r.id, name: r.name, short: r.short_name || r.name, region: r.region, group: r.group || null });
  });
  const muscleIds = new Set(muscles.map((m) => m.id));
  groups.forEach((g) => { if (!muscles.some((m) => m.group === g.id)) warnings.push(`${FILES.groups[1]}: group "${g.id}" has no muscles assigned to it in ${FILES.muscles[1]}`); });

  /* evidence sources */
  const sources: EvidenceSource[] = [];
  read(FILES.sources, ["id", "label", "citation", "url"], problems, true).forEach((r) => {
    const where = at(FILES.sources, r);
    if (!SLUG.test(r.id)) return problems.push(`${where}: id "${r.id}" must be lowercase words joined by hyphens`);
    if (sources.some((s) => s.id === r.id)) return problems.push(`${where}: duplicate source id "${r.id}"`);
    if (!/^https?:\/\//.test(r.url)) return problems.push(`${where}: url "${r.url}" must start with http(s)://`);
    sources.push({ id: r.id, label: r.label, citation: r.citation, url: r.url });
  });
  const sourceIds = new Set(sources.map((s) => s.id));

  /* exercises (curated first, then imported) */
  const exercises: Exercise[] = [];
  const catIds = new Set(categories.map((c) => c.id));
  /** exercises that failed validation; their rating rows are skipped instead of reported again */
  const rejected = new Set<string>();
  const exerciseFiles = [FILES.exercises, FILES.importedExercises] as const;
  exerciseFiles.forEach((file, fileIndex) => read(file, ["id", "name", "category"], problems, fileIndex > 0).forEach((r) => {
    const where = at(file, r);
    const bad = (msg: string) => { problems.push(msg); rejected.add(r.id); };
    if (!SLUG.test(r.id)) return problems.push(`${where}: id "${r.id}" must be lowercase words joined by hyphens (it becomes the page URL)`);
    if (exercises.some((e) => e.id === r.id)) return problems.push(`${where}: duplicate exercise id "${r.id}"`);
    if (!r.name) return bad(`${where}: name is empty`);
    if (!catIds.has(r.category)) return bad(`${where}: category "${r.category}" is not an id in ${FILES.categories[1]} (${[...catIds].join(", ")})`);
    let kind: DrillKind | null = null;
    if (r.kind) {
      const k = DRILL_KINDS.find((d) => d.toLowerCase() === r.kind.toLowerCase());
      if (!k) return bad(`${where}: kind "${r.kind}" must be empty or one of ${DRILL_KINDS.join(", ")}`);
      kind = k;
    }
    const joints = splitList(r.joints, /[;,|]/);
    const badJ = joints.filter((j) => !JOINTS[j]);
    if (badJ.length) return bad(`${where}: unknown joint(s) ${badJ.join(", ")} — use ${Object.keys(JOINTS).join(", ")}`);
    const demoId = r.demo || r.id;
    let demo: string | null = demoId;
    if (!DEMOS[demoId]) {
      if (r.demo) return bad(`${where}: demo "${r.demo}" doesn't exist in src/data/demos.ts`);
      // no demo is fine: the UI simply shows none for this exercise
      demo = null;
    }
    const steps = splitList(r.steps), cues = splitList(r.cues), mistakes = splitList(r.mistakes);
    if (!r.setup) warnings.push(`${where}: "${r.id}" has no setup text`);
    if (!steps.length) warnings.push(`${where}: "${r.id}" has no steps`);
    exercises.push({
      id: r.id, name: r.name, variant: r.variant || "", category: r.category, kind, joints, jointScores: {},
      equipment: r.equipment || "", mechanics: r.mechanics || "", level: r.level || "", demo, scores: {}, measured: [],
      setup: r.setup || "", steps, cues, mistakes, note: r.note || null, videoSearch: r.video_search || null,
      jointActions: {}, basis: {}, force: r.force || "",
      source: r.source_url ? { name: r.source_name || r.source || "Source", url: r.source_url } : null,
    });
  }));
  const exById = new Map(exercises.map((e) => [e.id, e]));

  /* exercise × muscle effort ratings */
  const scoreFiles = [FILES.scores, FILES.importedScores] as const;
  scoreFiles.forEach((file, fileIndex) => read(file, ["exercise_id", "muscle_id", "score"], problems, fileIndex > 0).forEach((r) => {
    const where = at(file, r);
    const e = exById.get(r.exercise_id);
    if (!e) { if (!rejected.has(r.exercise_id)) problems.push(`${where}: exercise "${r.exercise_id}" is not an id in the exercises files`); return; }
    if (!muscleIds.has(r.muscle_id)) return problems.push(`${where}: muscle "${r.muscle_id}" is not an id in ${FILES.muscles[1]}`);
    const n = Number(r.score);
    if (!Number.isInteger(n) || n < 1 || n > 5) return problems.push(`${where}: score "${r.score}" must be a whole number from 1 to 5`);
    if (e.scores[r.muscle_id] != null) return problems.push(`${where}: ${r.exercise_id} × ${r.muscle_id} is listed twice`);
    e.scores[r.muscle_id] = n;
    const basis: Basis = r.basis === "emg" ? "emg" : "model";
    if (r.basis && r.basis !== "emg" && r.basis !== "model") return problems.push(`${where}: basis "${r.basis}" must be emg or model`);
    if (basis === "emg") {
      const ids = splitList(r.sources, /[;|]/);
      const unknown = ids.filter((s) => !sourceIds.has(s));
      if (!ids.length) return problems.push(`${where}: an "emg" rating needs a source id in the sources column`);
      if (unknown.length) return problems.push(`${where}: unknown source(s) ${unknown.join(", ")} — add them to ${rel(...FILES.sources)}`);
      e.measured.push(r.muscle_id);
      e.basis[r.muscle_id] = ids;
    }
  }));
  exercises.forEach((e) => { if (!Object.keys(e.scores).length) warnings.push(`"${e.id}" has no muscle ratings, so it won't light up the map or show in comparisons`); });

  /* exercise × joint load scores */
  read(FILES.joints, ["exercise_id", "joint_id", "score", "action"], problems, true).forEach((r) => {
    const where = at(FILES.joints, r);
    const e = exById.get(r.exercise_id);
    if (!e) { if (!rejected.has(r.exercise_id)) problems.push(`${where}: exercise "${r.exercise_id}" is not an id in the exercises files`); return; }
    if (!JOINTS[r.joint_id]) return problems.push(`${where}: unknown joint "${r.joint_id}" — use ${Object.keys(JOINTS).join(", ")}`);
    const n = Number(r.score);
    if (!Number.isInteger(n) || n < 1 || n > 5) return problems.push(`${where}: score "${r.score}" must be a whole number from 1 to 5`);
    if (e.jointScores[r.joint_id] != null) return problems.push(`${where}: ${r.exercise_id} × ${r.joint_id} is listed twice`);
    e.jointScores[r.joint_id] = n;
    if (r.action) e.jointActions[r.joint_id] = r.action;
  });
  /* With joint scores, the joints that carry the exercise come from them; otherwise the `joints` column stands. */
  exercises.forEach((e) => {
    const ids = Object.keys(e.jointScores);
    if (!ids.length) { e.joints.forEach((j) => { e.jointScores[j] = 4; }); return; }
    const min = e.kind === "Stretch" || e.kind === "Mobility" ? 3 : 4;
    e.joints = ids.filter((j) => e.jointScores[j] >= min).sort((a, b) => e.jointScores[b] - e.jointScores[a]);
  });

  if (!exercises.length && !problems.length) problems.push("no exercises found");
  if (problems.length) throw new DataError(problems);
  return { data: { muscles, groups, categories, exercises, sources }, warnings };
}
